@triton.jit
def _stable_hypot(re, im):
    """``sqrt(re^2 + im^2)`` without overflowing a large finite component.

    The scaled form ``big * sqrt(1 + (small/big)^2)`` keeps the squares in
    ``[0, 1]``, so a component near the fp32 maximum reaches the result instead
    of overflowing to inf.  libdevice's ``hypot`` measures as the naive
    ``sqrt(re^2 + im^2)`` on this backend, which is why this is written out.
    """
