_TRUNC_FAST_DTYPES = (torch.float16, torch.bfloat16, torch.float32)


@triton.jit
def _trunc_tile(xp, pid, n, EVEN: tl.constexpr, BLOCK: tl.constexpr):
    """One tile of ``xp[i] = trunc(xp[i])``, in place.

    ``xp.dtype.element_ty`` is a compile-time constant, so a launch that mixes
    dtypes in one bucket still gets the right body per slot.

    fp32: ``floor`` below zero and ``ceil`` above it.  Both lower to native
    rounding instructions, and this three-op form measured faster than the
    fp -> int -> fp round trip (which needs a range guard for the values the
    cast is not defined for) at every size.  It is also exact at ``+-inf``,
    NaN and ``-0.0``: the comparison is false for all three negative-signed
    non-numbers, and ``floor`` passes them through unchanged.

    16-bit: ``floor`` is already ``trunc`` on ``|x|``, so the sign bit is copied
    back from the operand instead of paying for a second rounding op and a
    select.  The bitcast keeps the body on half-width lanes, which is what makes
    this path the fastest of everything measured (``ceil``/``floor`` +
    select, fp32 promote, and the ``int16`` round trip all measured slower).
    """
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        v = tl.load(xp + offs)
    else:
        m = offs < n
        v = tl.load(xp + offs, mask=m)
    if xp.dtype.element_ty == tl.float32:
        y = tl.where(v < 0.0, tl.ceil(v), tl.floor(v))
    else:
        ib = v.to(tl.int16, bitcast=True)
        y = (tl.floor(tl.abs(v)).to(tl.int16, bitcast=True) | (ib & -32768)).to(
            xp.dtype.element_ty, bitcast=True
        )
    if EVEN:
        tl.store(xp + offs, y)
    else:
        tl.store(xp + offs, y, mask=m)


